attempts.raw:
{"plan": "Inicializo a conta Ledger via baseline com initial_supply=100 e user_balance=0. O uso legitimo de burn com amount=0 deve ter sucesso. O ataque chama burn com amount=1 quando user_balance=0, tentando causar underflow; como o codigo usa checked_sub, o ataque deve ser rejeitado com ArithmeticUnderflow. Se por acaso o ataque tivesse sucesso, o efeito mediria user_balance com wrap-around (u64::MAX).", "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let (system_id, system_acc) = system_program_account();
let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    (system_id, system_acc),
];

let r_init = env.baseline("initialize ledger with supply 100", &init_ix, &init_accounts);

let ledger_after_init = after(&r_init, &ledger_key).clone();

let burn_ix = env.anchor_ix(
    "burn",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let burn_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let r = env.attack("burn 1 with user_balance 0 (underflow)", &burn_ix, &burn_accounts);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &ledger_key).data();
    let user_balance = read_u64(data, 40);
    let total_supply = read_u64(data, 48);
    env.effect(
        "user_balance wrapped around to u64::MAX (underflow)",
        user_balance == u64::MAX,
    );
    env.effect(
        "total_supply wrapped around to u64::MAX (underflow)",
        total_supply == u64::MAX,
    );
}"}

